// axi4_lite_regs_tb: self-checking directed testbench for axi4_lite_regs.
// Inputs are driven after the falling edge and outputs sampled before the
// rising edge, so there is no race with the design.
`default_nettype none

module axi4_lite_regs_tb;
    localparam [1:0] OKAY   = 2'b00;
    localparam [1:0] SLVERR = 2'b10;

    reg         aclk;
    reg         aresetn;
    reg  [3:0]  awaddr;
    reg         awvalid;
    wire        awready;
    reg  [31:0] wdata;
    reg  [3:0]  wstrb;
    reg         wvalid;
    wire        wready;
    wire [1:0]  bresp;
    wire        bvalid;
    reg         bready;
    reg  [3:0]  araddr;
    reg         arvalid;
    wire        arready;
    wire [31:0] rdata;
    wire [1:0]  rresp;
    wire        rvalid;
    reg         rready;

    integer passed;
    integer failed;
    integer rc;
    reg [31:0] model [0:3];
    reg [8*64-1:0] nonce;

    axi4_lite_regs #(
        .ADDR_WIDTH(4),
        .DATA_WIDTH(32)
    ) dut (
        .aclk           (aclk),
        .aresetn        (aresetn),
        .s_axil_awaddr  (awaddr),
        .s_axil_awvalid (awvalid),
        .s_axil_awready (awready),
        .s_axil_wdata   (wdata),
        .s_axil_wstrb   (wstrb),
        .s_axil_wvalid  (wvalid),
        .s_axil_wready  (wready),
        .s_axil_bresp   (bresp),
        .s_axil_bvalid  (bvalid),
        .s_axil_bready  (bready),
        .s_axil_araddr  (araddr),
        .s_axil_arvalid (arvalid),
        .s_axil_arready (arready),
        .s_axil_rdata   (rdata),
        .s_axil_rresp   (rresp),
        .s_axil_rvalid  (rvalid),
        .s_axil_rready  (rready)
    );

    initial begin
        aclk = 1'b0;
        forever #5 aclk = ~aclk;
    end

    // Watchdog: a hung run ends with no verdict, which is a failed run.
    initial begin
        #200000;
        $fatal(1, "timeout: the testbench did not finish");
    end

    // ------------------------------------------------------------------
    // Checking helpers
    // ------------------------------------------------------------------
    task automatic check(input cond, input [8*80-1:0] msg);
        begin
            if (cond) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("CHECK FAILED: %0s", msg);
            end
        end
    endtask

    task automatic check_eq32(input [31:0] act, input [31:0] expv, input [8*80-1:0] msg);
        begin
            if (act === expv) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("CHECK FAILED: %0s: got 0x%08h, expected 0x%08h", msg, act, expv);
            end
        end
    endtask

    function [31:0] merge32(input [31:0] old_v, input [31:0] new_v, input [3:0] strb);
        begin
            merge32 = {strb[3] ? new_v[31:24] : old_v[31:24],
                       strb[2] ? new_v[23:16] : old_v[23:16],
                       strb[1] ? new_v[15:8]  : old_v[15:8],
                       strb[0] ? new_v[7:0]   : old_v[7:0]};
        end
    endfunction

    function [1:0] exp_resp(input [3:0] a);
        begin
            exp_resp = (a[1:0] == 2'b00) ? OKAY : SLVERR;
        end
    endfunction

    function [31:0] exp_rdata(input [3:0] a);
        begin
            if (a[1:0] == 2'b00) exp_rdata = model[a[3:2]];
            else                 exp_rdata = 32'h0000_0000;
        end
    endfunction

    // ------------------------------------------------------------------
    // Write transaction
    //   order : 0 = AW and W together, 1 = AW first, 2 = W first
    //   gap   : idle cycles between the first and the second half
    //   bdelay: cycles BREADY stays low after BVALID; negative = BREADY early
    // Starts and ends just after a falling edge.
    // ------------------------------------------------------------------
    task automatic axi_write(input [3:0] addr, input [31:0] data, input [3:0] strb,
                             input integer order, input integer gap, input integer bdelay);
        integer gap_cnt;
        integer guard;
        integer lat;
        integer k;
        reg aw_done;
        reg w_done;
        reg aw_fire;
        reg w_fire;
        reg [1:0] expr;
        reg [1:0] resp_hold;
        begin
            expr    = exp_resp(addr);
            aw_done = 1'b0;
            w_done  = 1'b0;
            gap_cnt = 0;
            guard   = 0;
            if (bdelay < 0) bready = 1'b1;
            else            bready = 1'b0;
            if (order != 2) begin
                awaddr  = addr;
                awvalid = 1'b1;
            end
            if (order != 1) begin
                wdata  = data;
                wstrb  = strb;
                wvalid = 1'b1;
            end
            while (!(aw_done && w_done) && (guard < 32)) begin
                if (aw_done && !w_done) check(!awready, "write: AWREADY low while the address is held");
                if (w_done && !aw_done) check(!wready, "write: WREADY low while the data is held");
                check(!bvalid, "write: no BVALID before AW and W are both accepted");
                aw_fire = awvalid && awready;
                w_fire  = wvalid && wready;
                @(posedge aclk);
                @(negedge aclk);
                guard = guard + 1;
                if (aw_fire) begin
                    aw_done = 1'b1;
                    awvalid = 1'b0;
                    awaddr  = ~addr;
                end
                if (w_fire) begin
                    w_done = 1'b1;
                    wvalid = 1'b0;
                    wdata  = ~data;
                    wstrb  = ~strb;
                end
                if (aw_done && !w_done && !wvalid) begin
                    if (gap_cnt >= gap) begin
                        wdata  = data;
                        wstrb  = strb;
                        wvalid = 1'b1;
                    end else begin
                        gap_cnt = gap_cnt + 1;
                    end
                end
                if (w_done && !aw_done && !awvalid) begin
                    if (gap_cnt >= gap) begin
                        awaddr  = addr;
                        awvalid = 1'b1;
                    end else begin
                        gap_cnt = gap_cnt + 1;
                    end
                end
            end
            check(aw_done && w_done, "write: AW and W both accepted");
            if (expr == OKAY) model[addr[3:2]] = merge32(model[addr[3:2]], data, strb);

            // Latency: 1 means BVALID is high at the first rising edge after
            // the edge that completed the request.
            lat = 1;
            while (!bvalid && (lat < 4)) begin
                @(posedge aclk);
                @(negedge aclk);
                lat = lat + 1;
            end
            check(bvalid, "write: BVALID rises");
            check(lat <= 2, "write: B latency at most 2 cycles");
            check(bresp === expr, "write: BRESP follows the address policy");
            check(!awready && !wready, "write: no new write accepted while B pending");
            resp_hold = bresp;
            for (k = 0; k < bdelay; k = k + 1) begin
                @(posedge aclk);
                @(negedge aclk);
                check(bvalid, "write: BVALID holds under back-pressure");
                check(bresp === resp_hold, "write: BRESP holds under back-pressure");
                check(!awready && !wready, "write: AW/W blocked under B back-pressure");
            end
            bready = 1'b1;
            @(posedge aclk);
            @(negedge aclk);
            bready = 1'b0;
            check(!bvalid, "write: BVALID drops after the handshake");
            check(awready && wready, "write: AW/W ready the cycle after B is taken");
        end
    endtask

    // ------------------------------------------------------------------
    // Read transaction
    //   rdelay: cycles RREADY stays low after RVALID; negative = RREADY early
    // ------------------------------------------------------------------
    task automatic axi_read(input [3:0] addr, input integer rdelay);
        integer guard;
        integer lat;
        integer k;
        reg done;
        reg ar_fire;
        reg [31:0] expd;
        reg [1:0] expr;
        reg [31:0] data_hold;
        reg [1:0] resp_hold;
        begin
            expr  = exp_resp(addr);
            expd  = 32'h0000_0000;
            done  = 1'b0;
            guard = 0;
            if (rdelay < 0) rready = 1'b1;
            else            rready = 1'b0;
            araddr  = addr;
            arvalid = 1'b1;
            while (!done && (guard < 32)) begin
                check(!rvalid, "read: no RVALID before AR is accepted");
                ar_fire = arvalid && arready;
                if (ar_fire) expd = exp_rdata(addr);
                @(posedge aclk);
                @(negedge aclk);
                guard = guard + 1;
                if (ar_fire) begin
                    done    = 1'b1;
                    arvalid = 1'b0;
                    araddr  = ~addr;
                end
            end
            check(done, "read: AR accepted");
            lat = 1;
            while (!rvalid && (lat < 4)) begin
                @(posedge aclk);
                @(negedge aclk);
                lat = lat + 1;
            end
            check(rvalid, "read: RVALID rises");
            check(lat <= 2, "read: R latency at most 2 cycles");
            check_eq32(rdata, expd, "read: RDATA matches the model");
            check(rresp === expr, "read: RRESP follows the address policy");
            check(!arready, "read: no new read accepted while R pending");
            data_hold = rdata;
            resp_hold = rresp;
            for (k = 0; k < rdelay; k = k + 1) begin
                @(posedge aclk);
                @(negedge aclk);
                check(rvalid, "read: RVALID holds under back-pressure");
                check_eq32(rdata, data_hold, "read: RDATA holds under back-pressure");
                check(rresp === resp_hold, "read: RRESP holds under back-pressure");
                check(!arready, "read: AR blocked under R back-pressure");
            end
            rready = 1'b1;
            @(posedge aclk);
            @(negedge aclk);
            rready = 1'b0;
            check(!rvalid, "read: RVALID drops after the handshake");
            check(arready, "read: AR ready the cycle after R is taken");
        end
    endtask

    task automatic read_all;
        begin
            axi_read(4'h0, 0);
            axi_read(4'h4, 0);
            axi_read(4'h8, 0);
            axi_read(4'hC, 0);
        end
    endtask

    // ------------------------------------------------------------------
    // Test sequence
    // ------------------------------------------------------------------
    initial begin
        passed = 0;
        failed = 0;
        nonce  = {(8*64){1'b0}};
        rc = $value$plusargs("nirmaan_nonce=%s", nonce);
        if (rc == 0) $display("note: no nirmaan_nonce plusarg given");

        model[0] = 32'h0000_0000;
        model[1] = 32'h0000_0000;
        model[2] = 32'h0000_0000;
        model[3] = 32'h0000_0000;

        aresetn = 1'b0;
        awaddr  = 4'h0;
        awvalid = 1'b0;
        wdata   = 32'h0000_0000;
        wstrb   = 4'h0;
        wvalid  = 1'b0;
        bready  = 1'b0;
        araddr  = 4'h0;
        arvalid = 1'b0;
        rready  = 1'b0;

        // Reset
        repeat (3) @(negedge aclk);
        check(!bvalid && !rvalid, "reset: BVALID and RVALID low during reset");
        aresetn = 1'b1;
        @(negedge aclk);
        check(!bvalid && !rvalid, "reset: BVALID and RVALID low after reset");
        check(awready && wready && arready, "reset: AW, W and AR ready after reset");

        // 1. Reset values
        read_all;

        // 2. Write then read every register; AW/W orderings
        axi_write(4'h0, 32'hA5A5_0F0F, 4'hF, 0, 0, 0);
        axi_write(4'h4, 32'h1234_5678, 4'hF, 1, 0, 0);
        axi_write(4'h8, 32'hDEAD_BEEF, 4'hF, 2, 0, 0);
        axi_write(4'hC, 32'hCAFE_F00D, 4'hF, 1, 3, 0);
        read_all;
        axi_write(4'h4, 32'h0BAD_F00D, 4'hF, 2, 4, 0);
        axi_read(4'h4, 0);

        // 3. Byte strobes, including an empty strobe
        axi_write(4'h0, 32'h1111_1111, 4'b0001, 0, 0, 0);
        axi_read(4'h0, 0);
        axi_write(4'h0, 32'h2222_2222, 4'b0110, 1, 1, 0);
        axi_read(4'h0, 0);
        axi_write(4'h0, 32'h3333_3333, 4'b1000, 2, 1, 0);
        axi_read(4'h0, 0);
        axi_write(4'h8, 32'hFFFF_FFFF, 4'b0000, 0, 0, 0);
        axi_read(4'h8, 0);
        axi_write(4'hC, 32'h00AA_00AA, 4'b0101, 2, 0, 0);
        axi_read(4'hC, 0);

        // 4. B and R back-pressure
        axi_write(4'h8, 32'h5555_AAAA, 4'hF, 0, 0, 6);
        axi_read(4'h8, 6);
        axi_write(4'h4, 32'h7777_8888, 4'hF, 1, 2, 3);
        axi_read(4'h4, 3);

        // 5. Back-to-back transfers with READY raised early
        axi_write(4'h0, 32'h0000_0001, 4'hF, 0, 0, -1);
        axi_write(4'h4, 32'h0000_0002, 4'hF, 0, 0, -1);
        axi_write(4'h8, 32'h0000_0003, 4'hF, 0, 0, -1);
        axi_write(4'hC, 32'h0000_0004, 4'hF, 0, 0, -1);
        axi_read(4'h0, -1);
        axi_read(4'h4, -1);
        axi_read(4'h8, -1);
        axi_read(4'hC, -1);

        // 6. SLVERR policy for unmapped (misaligned) addresses
        axi_write(4'h5, 32'hBADB_AD00, 4'hF, 0, 0, 0);
        axi_write(4'hE, 32'hBADB_AD01, 4'hF, 1, 1, 2);
        axi_write(4'h3, 32'hBADB_AD02, 4'hF, 2, 0, 0);
        axi_read(4'h5, 0);
        axi_read(4'hE, 2);
        axi_read(4'h1, 0);
        read_all;

        // 7. Reads and writes on the same clock (different registers)
        fork
            axi_write(4'h8, 32'h8888_0008, 4'hF, 0, 0, 2);
            axi_read(4'h4, 1);
        join
        fork
            axi_write(4'hC, 32'hCCCC_000C, 4'hF, 2, 2, 0);
            axi_read(4'h0, -1);
        join
        fork
            axi_write(4'h0, 32'h0000_AAAA, 4'hF, 1, 0, -1);
            axi_read(4'h6, 0);
        join
        read_all;

        // 8. Reset during traffic: a half-accepted write is discarded
        awaddr  = 4'h4;
        awvalid = 1'b1;
        @(posedge aclk);
        @(negedge aclk);
        awvalid = 1'b0;
        awaddr  = 4'h0;
        check(!awready && wready && !bvalid, "reset test: AW held without W");
        araddr  = 4'h8;
        arvalid = 1'b1;
        @(posedge aclk);
        @(negedge aclk);
        arvalid = 1'b0;
        check(rvalid, "reset test: read response pending");
        aresetn = 1'b0;
        @(posedge aclk);
        @(negedge aclk);
        check(!bvalid && !rvalid, "reset test: responses cleared by reset");
        @(posedge aclk);
        @(negedge aclk);
        aresetn = 1'b1;
        @(posedge aclk);
        @(negedge aclk);
        check(awready && wready && arready && !bvalid && !rvalid,
              "reset test: idle after reset");
        model[0] = 32'h0000_0000;
        model[1] = 32'h0000_0000;
        model[2] = 32'h0000_0000;
        model[3] = 32'h0000_0000;
        wdata  = 32'hFFFF_FFFF;
        wstrb  = 4'hF;
        wvalid = 1'b1;
        @(posedge aclk);
        @(negedge aclk);
        wvalid = 1'b0;
        wdata  = 32'h0000_0000;
        wstrb  = 4'h0;
        check(!wready, "reset test: W held");
        repeat (3) begin
            check(!bvalid, "reset test: discarded AW does not pair with W");
            @(posedge aclk);
            @(negedge aclk);
        end
        awaddr  = 4'hC;
        awvalid = 1'b1;
        @(posedge aclk);
        @(negedge aclk);
        awvalid = 1'b0;
        check(bvalid && (bresp == OKAY), "reset test: write completes when AW arrives");
        bready = 1'b1;
        @(posedge aclk);
        @(negedge aclk);
        bready = 1'b0;
        check(!bvalid, "reset test: BVALID drops after the handshake");
        model[3] = 32'hFFFF_FFFF;
        read_all;

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

`default_nettype wire
